def find_ways(M):
    """Count sequences of length M over (+1, -1) with non-negative prefix sums and zero total sum.

    Each position contributes either +1 or -1. A sequence is counted iff
    every prefix sum is >= 0 and the final sum is 0 (balanced parentheses /
    Dyck path). For odd or negative M the count is 0; for M == 0 the empty
    sequence counts as 1.

    Example: find_ways(4) == 2 ([+1, +1, -1, -1] and [+1, -1, +1, -1]).
    """
    if M < 0:
        return 0
    if M % 2 == 1:
        return 0
    dp = [0] * (M + 2)
    dp[0] = 1
    for _ in range(M):
        nxt = [0] * (M + 2)
        for bal, cnt in enumerate(dp):
            if cnt == 0:
                continue
            # step +1
            if bal + 1 <= M:
                nxt[bal + 1] += cnt
            # step -1, only if it stays non-negative
            if bal > 0:
                nxt[bal - 1] += cnt
        dp = nxt
    return dp[0]
